The following standalone Python computes both bounds. It uses only standard Python. All matrix computations are modulo \(10^9+7\); that suffices for the stated bounds, since a nonzero minor modulo this prime certifies a nonzero rational minor. It also checks that every constructed Faber–Zagier relation is annihilated by every row of the intersection matrix.

```python
from collections import Counter, defaultdict
from functools import lru_cache
from math import factorial, comb, prod

p = 1_000_000_007
N = 12

def inv(x):
    return pow(x % p, -1, p)

@lru_cache(None)
def partitions(n, low=1):
    if n == 0:
        return ((),)
    return tuple(
        (a,) + b
        for a in range(low, n + 1)
        for b in partitions(n - a, a)
    )

def rank(rows):
    a = [list(row) for row in rows]
    r = 0
    for j in range(len(a[0])):
        pivot = next(
            (i for i in range(r, len(a)) if a[i][j] % p), None
        )
        if pivot is None:
            continue
        a[r], a[pivot] = a[pivot], a[r]
        z = inv(a[r][j])
        a[r] = [x * z % p for x in a[r]]
        for i in range(r + 1, len(a)):
            z = a[i][j]
            if z:
                a[i] = [
                    (x - z*y) % p for x, y in zip(a[i], a[r])
                ]
        r += 1
        if r == len(a):
            break
    return r

def series_mul(a, b):
    return [
        sum(a[i] * b[n-i] for i in range(n+1)) % p
        for n in range(N+1)
    ]

def series_div(a, b):
    q = []
    for n in range(N+1):
        q.append(
            (a[n] - sum(q[i]*b[n-i] for i in range(n)))
            * inv(b[0]) % p
        )
    return q

@lru_cache(None)
def submultisets(s):
    out = [()]
    for a, m in sorted(Counter(s).items()):
        out = [t + (a,)*j for t in out for j in range(m+1)]
    return tuple(out)

def difference(s, t):
    c = Counter(s)
    c.subtract(t)
    return tuple(a for a in sorted(c) for _ in range(c[a]))

# Faber--Zagier series.
A = [
    factorial(6*n)//factorial(3*n)//factorial(2*n) % p
    for n in range(N+1)
]
B = [a*(6*n+1)*inv(6*n-1) % p for n, a in enumerate(A)]
D = series_div(B, A)
derivative_A = [i*A[i] % p for i in range(1, N+1)] + [0]
logA = [0] + [
    x*inv(i) % p
    for i, x in enumerate(series_div(derivative_A, A)[:N], 1)
]
Dpower = [[1] + [0]*N]
for _ in range(10):
    Dpower.append(series_mul(Dpower[-1], D))

sigmas = [
    s for w in range(11) for s in partitions(w)
    if all(a % 3 != 2 for a in s)
]
sigmas.sort(key=lambda s: (len(s), s))

# E[s] is the coefficient of p_s in exp(-{log(Psi)}_kappa).
# A dictionary key is a kappa monomial, represented by its partition.
E = {}
for s in sigmas:
    if not s:
        E[s] = {
            lam: prod(
                pow(-logA[a] % p, m, p)*inv(factorial(m)) % p
                for a, m in Counter(lam).items()
            ) % p
            for d in range(N+1) for lam in partitions(d)
        }
        continue

    v = s[0]
    f = defaultdict(int)
    for t in submultisets(s):
        if v not in t:
            continue
        m = len(t)
        shift = sum(a//3 for a in t)
        j = sum(a % 3 == 1 for a in t)
        coefficient = (
            (-1)**m * factorial(m-1)
            * prod(inv(factorial(h)) for h in Counter(t).values())
            * t.count(v) * inv(s.count(v))
        ) % p

        for lam, x in E[difference(s, t)].items():
            for k in range(shift, N-sum(lam)+1):
                c = coefficient*Dpower[j][k-shift] % p
                if k == 0:
                    target = lam
                    c = 48*c % p       # kappa_0 = 2g-2
                else:
                    target = tuple(sorted(lam + (k,)))
                f[target] = (f[target] + x*c) % p
    E[s] = dict(f)

basis = partitions(12)
position = {s: i for i, s in enumerate(basis)}
relations = []

for d in range(1, 13):
    for s in sigmas:
        # g-1+|s| < 3d and g = d+|s|+1 mod 2.
        if 24 + sum(s) >= 3*d or (24-d-sum(s)) % 2:
            continue
        for multiplier in partitions(12-d):
            row = [0]*len(basis)
            for lam, c in E[s].items():
                if sum(lam) == d:
                    target = tuple(sorted(lam + multiplier))
                    row[position[target]] = c
            relations.append(row)

assert len(basis) == 77
assert len(relations) == 59
assert rank(relations) == 33

# Normalized lambda_g lambda_{g-1} intersection numbers.
#
# H(s)[k] is the sum over set partitions of the labelled entries
# of s into k blocks, with weight
# (-1)^(len(s)-k) / product_B (2*sum(B)+1)!!.
odd = [prod(range(1, 2*n+2, 2)) % p for n in range(24)]

@lru_cache(None)
def H(s):
    if not s:
        return (1,)
    v, rest = s[0], s[1:]
    counts = Counter(rest)
    answer = [0]*(len(s)+1)
    for t in submultisets(rest):
        tc = Counter(t)
        multiplicity = prod(comb(counts[a], m) for a, m in tc.items())
        c = (
            multiplicity * (-1)**len(t)
            * inv(odd[v+sum(t)])
        ) % p
        for k, x in enumerate(H(difference(rest, t))):
            answer[k+1] = (answer[k+1] + c*x) % p
    return tuple(answer)

@lru_cache(None)
def intersection(s):
    assert sum(s) == 23
    return sum(
        x * (factorial(47+k)//factorial(48)) * odd[23]
        for k, x in enumerate(H(s)) if k >= 1
    ) % p

pairing = [
    [intersection(tuple(sorted(a+b))) for b in basis]
    for a in partitions(11)
]

assert len(pairing) == 56
assert rank(pairing) == 43
assert all(
    sum(x*y for x, y in zip(r, q)) % p == 0
    for r in relations for q in pairing
)

print("Certified upper bound:", len(basis)-rank(relations))
print("Certified lower bound:", rank(pairing))
```

